(window.__qhadithX=window.__qhadithX||{})[74]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 1401","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1401","x":"Narrated Amr ibn al-'As:\n\nThe Prophet (ﷺ) taught me fifteen prostrations while reciting the Qur'an, including three in al-Mufassal and two in Surah al-Hajj. Abu Dawud said: Abu al-Darda' has reported eleven prostrations from the Prophet (ﷺ), but chain of this tradition is weak.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ بْنِ الْبَرْقِيِّ، حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا نَافِعُ بْنُ يَزِيدَ، عَنِ الْحَارِثِ بْنِ سَعِيدٍ الْعُتَقِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مُنَيْنٍ، - مِنْ بَنِي عَبْدِ كُلاَلٍ - عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَقْرَأَهُ خَمْسَ عَشْرَةَ سَجْدَةً فِي الْقُرْآنِ مِنْهَا ثَلاَثٌ فِي الْمُفَصَّلِ وَفِي سُورَةِ الْحَجِّ سَجْدَتَانِ ‏.‏ قَالَ أَبُو دَاوُدَ رُوِيَ عَنْ أَبِي الدَّرْدَاءِ عَنِ النَّبِيِّ صلى الله عليه وسلم إِحْدَى عَشْرَةَ سَجْدَةً وَإِسْنَادُهُ وَاهٍ ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4","x":"Narrated Jabir bin 'Abdullah Al-Ansari (while talking about the period of pause in revelation) reporting the speech of the Prophet:\n\n\"While I was walking, all of a sudden I heard a voice from the sky. I looked up and saw the same angel who had visited me at the cave of Hira' sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, 'Wrap me (in blankets).' And then Allah revealed the following Holy Verses (of Quran): 'O you (i.e. Muhammad)! wrapped up in garments!' Arise and warn (the people against Allah's Punishment),... up to 'and desert the idols.' (74.1-5) After this the revelation started coming strongly, frequently and regularly.\"","ar":"قَالَ ابْنُ شِهَابٍ وَأَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيَّ، قَالَ ـ وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ، فَقَالَ ـ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي، إِذْ سَمِعْتُ صَوْتًا، مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ‏}‏ إِلَى قَوْلِهِ ‏{‏وَالرُّجْزَ فَاهْجُرْ‏}‏ فَحَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏ تَابَعَهُ عَبْدُ اللَّهِ بْنُ يُوسُفَ وَأَبُو صَالِحٍ‏.‏ وَتَابَعَهُ هِلاَلُ بْنُ رَدَّادٍ عَنِ الزُّهْرِيِّ‏.‏ وَقَالَ يُونُسُ وَمَعْمَرٌ ‏\"‏ بَوَادِرُهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3238","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3238","x":"Narrated Jabir bin `Abdullah:\n\nthat he heard the Prophet (ﷺ) saying, \"The Divine Inspiration was delayed for a short period but suddenly, as I was walking. I heard a voice in the sky, and when I looked up towards the sky, to my surprise, I saw the angel who had come to me in the Hira Cave, and he was sitting on a chair in between the sky and the earth. I was so frightened by him that I fell on the ground and came to my family and said (to them), 'Cover me! (with a blanket), cover me!' Then Allah sent the Revelation: \"O, You wrapped up (In a blanket)! (Arise and warn! And your Lord magnify And keep pure your garments, And desert the idols.\" (74.1-5)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، قَالَ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ ـ رضى الله عنهما ـ أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\"‏ ثُمَّ فَتَرَ عَنِّي الْوَحْىُ فَتْرَةً، فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجُئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى ‏{‏فَاهْجُرْ‏}‏ ‏\"‏‏.‏ قَالَ أَبُو سَلَمَةَ وَالرِّجْزُ الأَوْثَانُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4922","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4922","x":"Narrated Yahya bin Abi Kathir:\n\nI asked Aba Salama bin `Abdur-Rahman about the first Sura revealed of the Qur'an. He replied \"O you, wrapped-up (i.e. Al Muddaththir).\" I said, \"They say it was, 'Read, in the Name of your Lord Who created,' (i.e. Surat Al-`Alaq (the Clot).\" On that, Abu Salama said, \"I asked Jabir bin `Abdullah about that, saying the same as you have said, whereupon he said, 'I will not tell you except what Allah's Messenger (ﷺ) had told us. Allah's Messenger (ﷺ) said, \"I was in seclusion in the cave of Hiram', and after I completed the limited period of my seclusion. I came down (from the cave) and heard a voice calling me. I looked to my right, but saw nothing. Then I looked up and saw something. So I went to Khadija (the Prophet's wife) and told her to wrap me up and pour cold water on me. So they wrapped me up and poured cold water on me.\" Then, 'O you, (Muhammad) wrapped up! Arise and warn,' (Surat Al Muddaththir) was revealed.\" (74.1)","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنْ عَلِيِّ بْنِ الْمُبَارَكِ، عَنْ يَحْيَى بْنِ أَبِي كَثِيرٍ، سَأَلْتُ أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ عَنْ أَوَّلِ، مَا نَزَلَ مِنَ الْقُرْآنِ‏.‏ قَالَ ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ قُلْتُ يَقُولُونَ ‏{‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ‏}‏ فَقَالَ أَبُو سَلَمَةَ سَأَلْتُ جَابِرَ بْنَ عَبْدِ اللَّهِ رضى الله عنهما عَنْ ذَلِكَ وَقُلْتُ لَهُ مِثْلَ الَّذِي قُلْتَ فَقَالَ جَابِرٌ لاَ أُحَدِّثُكَ إِلاَّ مَا حَدَّثَنَا رَسُولُ اللَّهِ صلى الله عليه وسلم قَالَ ‏\"‏ جَاوَرْتُ بِحِرَاءٍ، فَلَمَّا قَضَيْتُ جِوَارِي هَبَطْتُ فَنُودِيتُ فَنَظَرْتُ عَنْ يَمِينِي فَلَمْ أَرَ شَيْئًا، وَنَظَرْتُ عَنْ شِمَالِي فَلَمْ أَرَ شَيْئًا، وَنَظَرْتُ أَمَامِي فَلَمْ أَرَ شَيْئًا، وَنَظَرْتُ خَلْفِي فَلَمْ أَرَ شَيْئًا، فَرَفَعْتُ رَأْسِي فَرَأَيْتُ شَيْئًا، فَأَتَيْتُ خَدِيجَةَ فَقُلْتُ دَثِّرُونِي وَصُبُّوا عَلَىَّ مَاءً بَارِدًا ـ قَالَ ـ فَدَثَّرُونِي وَصَبُّوا عَلَىَّ مَاءً بَارِدًا قَالَ فَنَزَلَتْ ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ * وَرَبَّكَ فَكَبِّرْ‏}‏ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4926","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4926","x":"Narrated Jabir bin `Abdullah:\n\nThat he heard Allah's Messenger (ﷺ) describing the period of pause of the Divine Inspiration, and in his description he said, \"While I was walking I heard a voice from the sky. I looked up towards the sky, and behold! I saw the same Angel who came to me in the Cave of Hira', sitting on a chair between the sky and the earth. I was so terrified by him that I fell down on the ground. Then I went to my wife and said, 'Wrap me in garments! Wrap me in garments!' They wrapped me, and then Allah revealed: \"O you, (Muhammad) wrapped-up! Arise and warn...and desert the idols.\" (74.1-5) Abu Salama said....Rujz means idols.\" After that, the Divine Inspiration started coming more frequently and regularly.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، قَالَ ابْنُ شِهَابٍ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ ‏\"‏ فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجَئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَزَمَّلُونِي فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى قَوْلِهِ ‏{‏فَاهْجُرْ‏}‏ ‏\"‏ ـ قَالَ أَبُو سَلَمَةَ وَالرِّجْزَ الأَوْثَانَ ـ ‏\"‏ ثُمَّ حَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4954","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4954","x":"Narrated Jabir bin `Abdullah:\n\nWhile Allah's Messenger (ﷺ) was talking about the period of pause in revelation. he said in his narration. \"Once while I was walking, all of a sudden I heard a voice from the sky. I looked up and saw to my surprise, the same Angel as had visited me in the cave of Hira.' He was sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, Wrap me! Wrap me!\" So they covered him and then Allah revealed: 'O you, wrapped up! Arise and warn and your Lord magnify, and your garments purify and dessert the idols.' (74.1-5) Abu Salama said, \"(Rijz) are the idols which the people of the Pre-lslamic period used to worship.\" After this the revelation started coming frequently and regularly.","ar":"قَالَ مُحَمَّدُ بْنُ شِهَابٍ فَأَخْبَرَنِي أَبُو سَلَمَةَ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيِّ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَهْوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ قَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَفَرِقْتُ مِنْهُ فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏\"‏‏.‏ فَدَثَّرُوهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ * وَرَبَّكَ فَكَبِّرْ * وَثِيَابَكَ فَطَهِّرْ * وَالرِّجْزَ فَاهْجُرْ‏}‏‏.‏ قَالَ أَبُو سَلَمَةَ وَهْىَ الأَوْثَانُ الَّتِي كَانَ أَهْلُ الْجَاهِلِيَّةِ يَعْبُدُونَ‏.‏ قَالَ ثُمَّ تَتَابَعَ الْوَحْىُ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3325","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3325","x":"Jabir bin Abdullah [may Allah be pleased with him] said:\n\n\"I heard the Messenger of Allah – and he was narrating about the pause in Revelation – so he said in his narration: \"I was walking, when I heard a voice from the heavens. So I raised my head, and there was an angel, the one that had come to me at Hira, sitting upon a chair between the heavens and the earth. I fled from him out of fear, and I returned and said: ‘Wrap me up! Wrap me up! So they covered me.\" Then Allah, Most High revealed: ‘O you who are wrapped up! Arise and warm.’ Up to His saying: ‘And keep away from the Rujz!’ before the Salat was made obligatory.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رضى الله عنهما قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ فَقَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَمَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ رَأْسِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءَ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَجُثِثْتُ مِنْهُ رُعْبًا فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏.‏ فَدَثَّرُونِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏:‏ ‏(‏ يا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ والرُّجْزَ فَاهْجُرْ ‏)‏ قَبْلَ أَنْ تُفْرَضَ الصَّلاَةُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ يَحْيَى بْنُ أَبِي كَثِيرٍ عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ عَنْ جَابِرٍ أَبُو سَلَمَةَ اسْمُهُ عَبْدُ اللَّهِ ‏.‏","v":[]}],"2":[{"c":"Sahih Bukhari","r":"Hadith 4","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4","x":"Narrated Jabir bin 'Abdullah Al-Ansari (while talking about the period of pause in revelation) reporting the speech of the Prophet:\n\n\"While I was walking, all of a sudden I heard a voice from the sky. I looked up and saw the same angel who had visited me at the cave of Hira' sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, 'Wrap me (in blankets).' And then Allah revealed the following Holy Verses (of Quran): 'O you (i.e. Muhammad)! wrapped up in garments!' Arise and warn (the people against Allah's Punishment),... up to 'and desert the idols.' (74.1-5) After this the revelation started coming strongly, frequently and regularly.\"","ar":"قَالَ ابْنُ شِهَابٍ وَأَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيَّ، قَالَ ـ وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ، فَقَالَ ـ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي، إِذْ سَمِعْتُ صَوْتًا، مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ‏}‏ إِلَى قَوْلِهِ ‏{‏وَالرُّجْزَ فَاهْجُرْ‏}‏ فَحَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏ تَابَعَهُ عَبْدُ اللَّهِ بْنُ يُوسُفَ وَأَبُو صَالِحٍ‏.‏ وَتَابَعَهُ هِلاَلُ بْنُ رَدَّادٍ عَنِ الزُّهْرِيِّ‏.‏ وَقَالَ يُونُسُ وَمَعْمَرٌ ‏\"‏ بَوَادِرُهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3238","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3238","x":"Narrated Jabir bin `Abdullah:\n\nthat he heard the Prophet (ﷺ) saying, \"The Divine Inspiration was delayed for a short period but suddenly, as I was walking. I heard a voice in the sky, and when I looked up towards the sky, to my surprise, I saw the angel who had come to me in the Hira Cave, and he was sitting on a chair in between the sky and the earth. I was so frightened by him that I fell on the ground and came to my family and said (to them), 'Cover me! (with a blanket), cover me!' Then Allah sent the Revelation: \"O, You wrapped up (In a blanket)! (Arise and warn! And your Lord magnify And keep pure your garments, And desert the idols.\" (74.1-5)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، قَالَ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ ـ رضى الله عنهما ـ أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\"‏ ثُمَّ فَتَرَ عَنِّي الْوَحْىُ فَتْرَةً، فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجُئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى ‏{‏فَاهْجُرْ‏}‏ ‏\"‏‏.‏ قَالَ أَبُو سَلَمَةَ وَالرِّجْزُ الأَوْثَانُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4926","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4926","x":"Narrated Jabir bin `Abdullah:\n\nThat he heard Allah's Messenger (ﷺ) describing the period of pause of the Divine Inspiration, and in his description he said, \"While I was walking I heard a voice from the sky. I looked up towards the sky, and behold! I saw the same Angel who came to me in the Cave of Hira', sitting on a chair between the sky and the earth. I was so terrified by him that I fell down on the ground. Then I went to my wife and said, 'Wrap me in garments! Wrap me in garments!' They wrapped me, and then Allah revealed: \"O you, (Muhammad) wrapped-up! Arise and warn...and desert the idols.\" (74.1-5) Abu Salama said....Rujz means idols.\" After that, the Divine Inspiration started coming more frequently and regularly.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، قَالَ ابْنُ شِهَابٍ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ ‏\"‏ فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجَئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَزَمَّلُونِي فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى قَوْلِهِ ‏{‏فَاهْجُرْ‏}‏ ‏\"‏ ـ قَالَ أَبُو سَلَمَةَ وَالرِّجْزَ الأَوْثَانَ ـ ‏\"‏ ثُمَّ حَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4954","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4954","x":"Narrated Jabir bin `Abdullah:\n\nWhile Allah's Messenger (ﷺ) was talking about the period of pause in revelation. he said in his narration. \"Once while I was walking, all of a sudden I heard a voice from the sky. I looked up and saw to my surprise, the same Angel as had visited me in the cave of Hira.' He was sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, Wrap me! Wrap me!\" So they covered him and then Allah revealed: 'O you, wrapped up! Arise and warn and your Lord magnify, and your garments purify and dessert the idols.' (74.1-5) Abu Salama said, \"(Rijz) are the idols which the people of the Pre-lslamic period used to worship.\" After this the revelation started coming frequently and regularly.","ar":"قَالَ مُحَمَّدُ بْنُ شِهَابٍ فَأَخْبَرَنِي أَبُو سَلَمَةَ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيِّ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَهْوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ قَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَفَرِقْتُ مِنْهُ فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏\"‏‏.‏ فَدَثَّرُوهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ * وَرَبَّكَ فَكَبِّرْ * وَثِيَابَكَ فَطَهِّرْ * وَالرِّجْزَ فَاهْجُرْ‏}‏‏.‏ قَالَ أَبُو سَلَمَةَ وَهْىَ الأَوْثَانُ الَّتِي كَانَ أَهْلُ الْجَاهِلِيَّةِ يَعْبُدُونَ‏.‏ قَالَ ثُمَّ تَتَابَعَ الْوَحْىُ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3325","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3325","x":"Jabir bin Abdullah [may Allah be pleased with him] said:\n\n\"I heard the Messenger of Allah – and he was narrating about the pause in Revelation – so he said in his narration: \"I was walking, when I heard a voice from the heavens. So I raised my head, and there was an angel, the one that had come to me at Hira, sitting upon a chair between the heavens and the earth. I fled from him out of fear, and I returned and said: ‘Wrap me up! Wrap me up! So they covered me.\" Then Allah, Most High revealed: ‘O you who are wrapped up! Arise and warm.’ Up to His saying: ‘And keep away from the Rujz!’ before the Salat was made obligatory.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رضى الله عنهما قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ فَقَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَمَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ رَأْسِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءَ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَجُثِثْتُ مِنْهُ رُعْبًا فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏.‏ فَدَثَّرُونِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏:‏ ‏(‏ يا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ والرُّجْزَ فَاهْجُرْ ‏)‏ قَبْلَ أَنْ تُفْرَضَ الصَّلاَةُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ يَحْيَى بْنُ أَبِي كَثِيرٍ عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ عَنْ جَابِرٍ أَبُو سَلَمَةَ اسْمُهُ عَبْدُ اللَّهِ ‏.‏","v":[]}],"3":[{"c":"Sahih Bukhari","r":"Hadith 4","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4","x":"Narrated Jabir bin 'Abdullah Al-Ansari (while talking about the period of pause in revelation) reporting the speech of the Prophet:\n\n\"While I was walking, all of a sudden I heard a voice from the sky. I looked up and saw the same angel who had visited me at the cave of Hira' sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, 'Wrap me (in blankets).' And then Allah revealed the following Holy Verses (of Quran): 'O you (i.e. Muhammad)! wrapped up in garments!' Arise and warn (the people against Allah's Punishment),... up to 'and desert the idols.' (74.1-5) After this the revelation started coming strongly, frequently and regularly.\"","ar":"قَالَ ابْنُ شِهَابٍ وَأَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيَّ، قَالَ ـ وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ، فَقَالَ ـ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي، إِذْ سَمِعْتُ صَوْتًا، مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ‏}‏ إِلَى قَوْلِهِ ‏{‏وَالرُّجْزَ فَاهْجُرْ‏}‏ فَحَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏ تَابَعَهُ عَبْدُ اللَّهِ بْنُ يُوسُفَ وَأَبُو صَالِحٍ‏.‏ وَتَابَعَهُ هِلاَلُ بْنُ رَدَّادٍ عَنِ الزُّهْرِيِّ‏.‏ وَقَالَ يُونُسُ وَمَعْمَرٌ ‏\"‏ بَوَادِرُهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3238","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3238","x":"Narrated Jabir bin `Abdullah:\n\nthat he heard the Prophet (ﷺ) saying, \"The Divine Inspiration was delayed for a short period but suddenly, as I was walking. I heard a voice in the sky, and when I looked up towards the sky, to my surprise, I saw the angel who had come to me in the Hira Cave, and he was sitting on a chair in between the sky and the earth. I was so frightened by him that I fell on the ground and came to my family and said (to them), 'Cover me! (with a blanket), cover me!' Then Allah sent the Revelation: \"O, You wrapped up (In a blanket)! (Arise and warn! And your Lord magnify And keep pure your garments, And desert the idols.\" (74.1-5)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، قَالَ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ ـ رضى الله عنهما ـ أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\"‏ ثُمَّ فَتَرَ عَنِّي الْوَحْىُ فَتْرَةً، فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجُئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى ‏{‏فَاهْجُرْ‏}‏ ‏\"‏‏.‏ قَالَ أَبُو سَلَمَةَ وَالرِّجْزُ الأَوْثَانُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4926","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4926","x":"Narrated Jabir bin `Abdullah:\n\nThat he heard Allah's Messenger (ﷺ) describing the period of pause of the Divine Inspiration, and in his description he said, \"While I was walking I heard a voice from the sky. I looked up towards the sky, and behold! I saw the same Angel who came to me in the Cave of Hira', sitting on a chair between the sky and the earth. I was so terrified by him that I fell down on the ground. Then I went to my wife and said, 'Wrap me in garments! Wrap me in garments!' They wrapped me, and then Allah revealed: \"O you, (Muhammad) wrapped-up! Arise and warn...and desert the idols.\" (74.1-5) Abu Salama said....Rujz means idols.\" After that, the Divine Inspiration started coming more frequently and regularly.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، قَالَ ابْنُ شِهَابٍ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ ‏\"‏ فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجَئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَزَمَّلُونِي فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى قَوْلِهِ ‏{‏فَاهْجُرْ‏}‏ ‏\"‏ ـ قَالَ أَبُو سَلَمَةَ وَالرِّجْزَ الأَوْثَانَ ـ ‏\"‏ ثُمَّ حَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4954","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4954","x":"Narrated Jabir bin `Abdullah:\n\nWhile Allah's Messenger (ﷺ) was talking about the period of pause in revelation. he said in his narration. \"Once while I was walking, all of a sudden I heard a voice from the sky. I looked up and saw to my surprise, the same Angel as had visited me in the cave of Hira.' He was sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, Wrap me! Wrap me!\" So they covered him and then Allah revealed: 'O you, wrapped up! Arise and warn and your Lord magnify, and your garments purify and dessert the idols.' (74.1-5) Abu Salama said, \"(Rijz) are the idols which the people of the Pre-lslamic period used to worship.\" After this the revelation started coming frequently and regularly.","ar":"قَالَ مُحَمَّدُ بْنُ شِهَابٍ فَأَخْبَرَنِي أَبُو سَلَمَةَ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيِّ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَهْوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ قَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَفَرِقْتُ مِنْهُ فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏\"‏‏.‏ فَدَثَّرُوهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ * وَرَبَّكَ فَكَبِّرْ * وَثِيَابَكَ فَطَهِّرْ * وَالرِّجْزَ فَاهْجُرْ‏}‏‏.‏ قَالَ أَبُو سَلَمَةَ وَهْىَ الأَوْثَانُ الَّتِي كَانَ أَهْلُ الْجَاهِلِيَّةِ يَعْبُدُونَ‏.‏ قَالَ ثُمَّ تَتَابَعَ الْوَحْىُ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3325","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3325","x":"Jabir bin Abdullah [may Allah be pleased with him] said:\n\n\"I heard the Messenger of Allah – and he was narrating about the pause in Revelation – so he said in his narration: \"I was walking, when I heard a voice from the heavens. So I raised my head, and there was an angel, the one that had come to me at Hira, sitting upon a chair between the heavens and the earth. I fled from him out of fear, and I returned and said: ‘Wrap me up! Wrap me up! So they covered me.\" Then Allah, Most High revealed: ‘O you who are wrapped up! Arise and warm.’ Up to His saying: ‘And keep away from the Rujz!’ before the Salat was made obligatory.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رضى الله عنهما قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ فَقَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَمَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ رَأْسِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءَ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَجُثِثْتُ مِنْهُ رُعْبًا فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏.‏ فَدَثَّرُونِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏:‏ ‏(‏ يا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ والرُّجْزَ فَاهْجُرْ ‏)‏ قَبْلَ أَنْ تُفْرَضَ الصَّلاَةُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ يَحْيَى بْنُ أَبِي كَثِيرٍ عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ عَنْ جَابِرٍ أَبُو سَلَمَةَ اسْمُهُ عَبْدُ اللَّهِ ‏.‏","v":[]}],"4":[{"c":"Sahih Bukhari","r":"Hadith 4","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4","x":"Narrated Jabir bin 'Abdullah Al-Ansari (while talking about the period of pause in revelation) reporting the speech of the Prophet:\n\n\"While I was walking, all of a sudden I heard a voice from the sky. I looked up and saw the same angel who had visited me at the cave of Hira' sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, 'Wrap me (in blankets).' And then Allah revealed the following Holy Verses (of Quran): 'O you (i.e. Muhammad)! wrapped up in garments!' Arise and warn (the people against Allah's Punishment),... up to 'and desert the idols.' (74.1-5) After this the revelation started coming strongly, frequently and regularly.\"","ar":"قَالَ ابْنُ شِهَابٍ وَأَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيَّ، قَالَ ـ وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ، فَقَالَ ـ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي، إِذْ سَمِعْتُ صَوْتًا، مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ‏}‏ إِلَى قَوْلِهِ ‏{‏وَالرُّجْزَ فَاهْجُرْ‏}‏ فَحَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏ تَابَعَهُ عَبْدُ اللَّهِ بْنُ يُوسُفَ وَأَبُو صَالِحٍ‏.‏ وَتَابَعَهُ هِلاَلُ بْنُ رَدَّادٍ عَنِ الزُّهْرِيِّ‏.‏ وَقَالَ يُونُسُ وَمَعْمَرٌ ‏\"‏ بَوَادِرُهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3238","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3238","x":"Narrated Jabir bin `Abdullah:\n\nthat he heard the Prophet (ﷺ) saying, \"The Divine Inspiration was delayed for a short period but suddenly, as I was walking. I heard a voice in the sky, and when I looked up towards the sky, to my surprise, I saw the angel who had come to me in the Hira Cave, and he was sitting on a chair in between the sky and the earth. I was so frightened by him that I fell on the ground and came to my family and said (to them), 'Cover me! (with a blanket), cover me!' Then Allah sent the Revelation: \"O, You wrapped up (In a blanket)! (Arise and warn! And your Lord magnify And keep pure your garments, And desert the idols.\" (74.1-5)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، قَالَ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ ـ رضى الله عنهما ـ أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\"‏ ثُمَّ فَتَرَ عَنِّي الْوَحْىُ فَتْرَةً، فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجُئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى ‏{‏فَاهْجُرْ‏}‏ ‏\"‏‏.‏ قَالَ أَبُو سَلَمَةَ وَالرِّجْزُ الأَوْثَانُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4926","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4926","x":"Narrated Jabir bin `Abdullah:\n\nThat he heard Allah's Messenger (ﷺ) describing the period of pause of the Divine Inspiration, and in his description he said, \"While I was walking I heard a voice from the sky. I looked up towards the sky, and behold! I saw the same Angel who came to me in the Cave of Hira', sitting on a chair between the sky and the earth. I was so terrified by him that I fell down on the ground. Then I went to my wife and said, 'Wrap me in garments! Wrap me in garments!' They wrapped me, and then Allah revealed: \"O you, (Muhammad) wrapped-up! Arise and warn...and desert the idols.\" (74.1-5) Abu Salama said....Rujz means idols.\" After that, the Divine Inspiration started coming more frequently and regularly.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، قَالَ ابْنُ شِهَابٍ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ ‏\"‏ فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجَئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَزَمَّلُونِي فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى قَوْلِهِ ‏{‏فَاهْجُرْ‏}‏ ‏\"‏ ـ قَالَ أَبُو سَلَمَةَ وَالرِّجْزَ الأَوْثَانَ ـ ‏\"‏ ثُمَّ حَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4954","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4954","x":"Narrated Jabir bin `Abdullah:\n\nWhile Allah's Messenger (ﷺ) was talking about the period of pause in revelation. he said in his narration. \"Once while I was walking, all of a sudden I heard a voice from the sky. I looked up and saw to my surprise, the same Angel as had visited me in the cave of Hira.' He was sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, Wrap me! Wrap me!\" So they covered him and then Allah revealed: 'O you, wrapped up! Arise and warn and your Lord magnify, and your garments purify and dessert the idols.' (74.1-5) Abu Salama said, \"(Rijz) are the idols which the people of the Pre-lslamic period used to worship.\" After this the revelation started coming frequently and regularly.","ar":"قَالَ مُحَمَّدُ بْنُ شِهَابٍ فَأَخْبَرَنِي أَبُو سَلَمَةَ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيِّ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَهْوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ قَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَفَرِقْتُ مِنْهُ فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏\"‏‏.‏ فَدَثَّرُوهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ * وَرَبَّكَ فَكَبِّرْ * وَثِيَابَكَ فَطَهِّرْ * وَالرِّجْزَ فَاهْجُرْ‏}‏‏.‏ قَالَ أَبُو سَلَمَةَ وَهْىَ الأَوْثَانُ الَّتِي كَانَ أَهْلُ الْجَاهِلِيَّةِ يَعْبُدُونَ‏.‏ قَالَ ثُمَّ تَتَابَعَ الْوَحْىُ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3325","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3325","x":"Jabir bin Abdullah [may Allah be pleased with him] said:\n\n\"I heard the Messenger of Allah – and he was narrating about the pause in Revelation – so he said in his narration: \"I was walking, when I heard a voice from the heavens. So I raised my head, and there was an angel, the one that had come to me at Hira, sitting upon a chair between the heavens and the earth. I fled from him out of fear, and I returned and said: ‘Wrap me up! Wrap me up! So they covered me.\" Then Allah, Most High revealed: ‘O you who are wrapped up! Arise and warm.’ Up to His saying: ‘And keep away from the Rujz!’ before the Salat was made obligatory.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رضى الله عنهما قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ فَقَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَمَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ رَأْسِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءَ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَجُثِثْتُ مِنْهُ رُعْبًا فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏.‏ فَدَثَّرُونِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏:‏ ‏(‏ يا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ والرُّجْزَ فَاهْجُرْ ‏)‏ قَبْلَ أَنْ تُفْرَضَ الصَّلاَةُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ يَحْيَى بْنُ أَبِي كَثِيرٍ عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ عَنْ جَابِرٍ أَبُو سَلَمَةَ اسْمُهُ عَبْدُ اللَّهِ ‏.‏","v":[]}],"5":[{"c":"Sahih Bukhari","r":"Hadith 4","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4","x":"Narrated Jabir bin 'Abdullah Al-Ansari (while talking about the period of pause in revelation) reporting the speech of the Prophet:\n\n\"While I was walking, all of a sudden I heard a voice from the sky. I looked up and saw the same angel who had visited me at the cave of Hira' sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, 'Wrap me (in blankets).' And then Allah revealed the following Holy Verses (of Quran): 'O you (i.e. Muhammad)! wrapped up in garments!' Arise and warn (the people against Allah's Punishment),... up to 'and desert the idols.' (74.1-5) After this the revelation started coming strongly, frequently and regularly.\"","ar":"قَالَ ابْنُ شِهَابٍ وَأَخْبَرَنِي أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيَّ، قَالَ ـ وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ، فَقَالَ ـ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي، إِذْ سَمِعْتُ صَوْتًا، مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَرُعِبْتُ مِنْهُ، فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ‏}‏ إِلَى قَوْلِهِ ‏{‏وَالرُّجْزَ فَاهْجُرْ‏}‏ فَحَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏ تَابَعَهُ عَبْدُ اللَّهِ بْنُ يُوسُفَ وَأَبُو صَالِحٍ‏.‏ وَتَابَعَهُ هِلاَلُ بْنُ رَدَّادٍ عَنِ الزُّهْرِيِّ‏.‏ وَقَالَ يُونُسُ وَمَعْمَرٌ ‏\"‏ بَوَادِرُهُ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 3238","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-3238","x":"Narrated Jabir bin `Abdullah:\n\nthat he heard the Prophet (ﷺ) saying, \"The Divine Inspiration was delayed for a short period but suddenly, as I was walking. I heard a voice in the sky, and when I looked up towards the sky, to my surprise, I saw the angel who had come to me in the Hira Cave, and he was sitting on a chair in between the sky and the earth. I was so frightened by him that I fell on the ground and came to my family and said (to them), 'Cover me! (with a blanket), cover me!' Then Allah sent the Revelation: \"O, You wrapped up (In a blanket)! (Arise and warn! And your Lord magnify And keep pure your garments, And desert the idols.\" (74.1-5)","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، أَخْبَرَنَا اللَّيْثُ، قَالَ حَدَّثَنِي عُقَيْلٌ، عَنِ ابْنِ شِهَابٍ، قَالَ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ ـ رضى الله عنهما ـ أَنَّهُ سَمِعَ النَّبِيَّ صلى الله عليه وسلم يَقُولُ ‏\"‏ ثُمَّ فَتَرَ عَنِّي الْوَحْىُ فَتْرَةً، فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ، فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجُئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى ‏{‏فَاهْجُرْ‏}‏ ‏\"‏‏.‏ قَالَ أَبُو سَلَمَةَ وَالرِّجْزُ الأَوْثَانُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4926","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4926","x":"Narrated Jabir bin `Abdullah:\n\nThat he heard Allah's Messenger (ﷺ) describing the period of pause of the Divine Inspiration, and in his description he said, \"While I was walking I heard a voice from the sky. I looked up towards the sky, and behold! I saw the same Angel who came to me in the Cave of Hira', sitting on a chair between the sky and the earth. I was so terrified by him that I fell down on the ground. Then I went to my wife and said, 'Wrap me in garments! Wrap me in garments!' They wrapped me, and then Allah revealed: \"O you, (Muhammad) wrapped-up! Arise and warn...and desert the idols.\" (74.1-5) Abu Salama said....Rujz means idols.\" After that, the Divine Inspiration started coming more frequently and regularly.","ar":"حَدَّثَنَا عَبْدُ اللَّهِ بْنُ يُوسُفَ، حَدَّثَنَا اللَّيْثُ، عَنْ عُقَيْلٍ، قَالَ ابْنُ شِهَابٍ سَمِعْتُ أَبَا سَلَمَةَ، قَالَ أَخْبَرَنِي جَابِرُ بْنُ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صلى الله عليه وسلم يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ ‏\"‏ فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي قِبَلَ السَّمَاءِ، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ قَاعِدٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ، فَجَئِثْتُ مِنْهُ حَتَّى هَوَيْتُ إِلَى الأَرْضِ، فَجِئْتُ أَهْلِي فَقُلْتُ زَمِّلُونِي زَمِّلُونِي‏.‏ فَزَمَّلُونِي فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ‏}‏ إِلَى قَوْلِهِ ‏{‏فَاهْجُرْ‏}‏ ‏\"‏ ـ قَالَ أَبُو سَلَمَةَ وَالرِّجْزَ الأَوْثَانَ ـ ‏\"‏ ثُمَّ حَمِيَ الْوَحْىُ وَتَتَابَعَ ‏\"‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4954","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4954","x":"Narrated Jabir bin `Abdullah:\n\nWhile Allah's Messenger (ﷺ) was talking about the period of pause in revelation. he said in his narration. \"Once while I was walking, all of a sudden I heard a voice from the sky. I looked up and saw to my surprise, the same Angel as had visited me in the cave of Hira.' He was sitting on a chair between the sky and the earth. I got afraid of him and came back home and said, Wrap me! Wrap me!\" So they covered him and then Allah revealed: 'O you, wrapped up! Arise and warn and your Lord magnify, and your garments purify and dessert the idols.' (74.1-5) Abu Salama said, \"(Rijz) are the idols which the people of the Pre-lslamic period used to worship.\" After this the revelation started coming frequently and regularly.","ar":"قَالَ مُحَمَّدُ بْنُ شِهَابٍ فَأَخْبَرَنِي أَبُو سَلَمَةَ، أَنَّ جَابِرَ بْنَ عَبْدِ اللَّهِ الأَنْصَارِيِّ ـ رضى الله عنهما ـ قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَهْوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ قَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ بَصَرِي، فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءٍ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَفَرِقْتُ مِنْهُ فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏\"‏‏.‏ فَدَثَّرُوهُ فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏يَا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ * وَرَبَّكَ فَكَبِّرْ * وَثِيَابَكَ فَطَهِّرْ * وَالرِّجْزَ فَاهْجُرْ‏}‏‏.‏ قَالَ أَبُو سَلَمَةَ وَهْىَ الأَوْثَانُ الَّتِي كَانَ أَهْلُ الْجَاهِلِيَّةِ يَعْبُدُونَ‏.‏ قَالَ ثُمَّ تَتَابَعَ الْوَحْىُ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 6, Book 44, Hadith 3325","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-6/Book-44/Hadith-3325","x":"Jabir bin Abdullah [may Allah be pleased with him] said:\n\n\"I heard the Messenger of Allah – and he was narrating about the pause in Revelation – so he said in his narration: \"I was walking, when I heard a voice from the heavens. So I raised my head, and there was an angel, the one that had come to me at Hira, sitting upon a chair between the heavens and the earth. I fled from him out of fear, and I returned and said: ‘Wrap me up! Wrap me up! So they covered me.\" Then Allah, Most High revealed: ‘O you who are wrapped up! Arise and warm.’ Up to His saying: ‘And keep away from the Rujz!’ before the Salat was made obligatory.\"","ar":"حَدَّثَنَا عَبْدُ بْنُ حُمَيْدٍ، أَخْبَرَنَا عَبْدُ الرَّزَّاقِ، حَدَّثَنَا مَعْمَرٌ، عَنِ الزُّهْرِيِّ، عَنْ أَبِي سَلَمَةَ، عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، رضى الله عنهما قَالَ سَمِعْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم وَهُوَ يُحَدِّثُ عَنْ فَتْرَةِ الْوَحْىِ فَقَالَ فِي حَدِيثِهِ ‏\"‏ بَيْنَمَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنَ السَّمَاءِ فَرَفَعْتُ رَأْسِي فَإِذَا الْمَلَكُ الَّذِي جَاءَنِي بِحِرَاءَ جَالِسٌ عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالأَرْضِ فَجُثِثْتُ مِنْهُ رُعْبًا فَرَجَعْتُ فَقُلْتُ زَمِّلُونِي زَمِّلُونِي ‏.‏ فَدَثَّرُونِي فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏:‏ ‏(‏ يا أَيُّهَا الْمُدَّثِّرُ * قُمْ فَأَنْذِرْ ‏)‏ إِلَى قَوْلِهِ ‏:‏ ‏(‏ والرُّجْزَ فَاهْجُرْ ‏)‏ قَبْلَ أَنْ تُفْرَضَ الصَّلاَةُ ‏\"‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ وَقَدْ رَوَاهُ يَحْيَى بْنُ أَبِي كَثِيرٍ عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ عَنْ جَابِرٍ أَبُو سَلَمَةَ اسْمُهُ عَبْدُ اللَّهِ ‏.‏","v":[]}],"56":[{"c":"Sunan Ibn Majah","r":"Volume 5, Book 37, Hadith 4299","u":"https://quranx.com/Hadith/IbnMajah/DarusSalam/Volume-5/Book-37/Hadith-4299","x":"It was narrated from Anas bin Malik that the Messenger of Allah (ﷺ) recited this Verse:\n\n\"He (Allah) is the One, deserving that mankind should be afraid of, and should be dutiful to Him, and should not take any Ilah (god) along with Him, and He is the One Who forgives (sins).\" [74:56] Then he said: \"Allah says: ‘I am the One Who deserves to be feared, so no other god should be appointed alongside Me. Whoever avoids appointing another god alongside Me, I am the One Who should forgive him.\" Another chain reports a similar hadith.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا زَيْدُ بْنُ الْحُبَابِ، حَدَّثَنَا سُهَيْلُ بْنُ عَبْدِ اللَّهِ، - أَخُو حَزْمٍ الْقُطَعِيِّ - حَدَّثَنَا ثَابِتٌ الْبُنَانِيُّ، عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَرَأَ - أَوْ تَلاَ - هَذِهِ الآيَةَ ‏{هُوَ أَهْلُ التَّقْوَى وَأَهْلُ الْمَغْفِرَةِ}‏ فَقَالَ ‏\"‏ قَالَ اللَّهُ عَزَّ وَجَلَّ أَنَا أَهْلٌ أَنْ أُتَّقَى فَلاَ يُجْعَلَ مَعِي إِلَهٌ آخَرُ فَمَنِ اتَّقَى أَنْ يَجْعَلَ مَعِي إِلَهًا آخَرَ فَأَنَا أَهْلٌ أَنْ أَغْفِرَ لَهُ ‏\"‏ ‏.‏ قَالَ أَبُو الْحَسَنِ الْقَطَّانُ حَدَّثَنَا إِبْرَاهِيمُ بْنُ نَصْرٍ، حَدَّثَنَا هُدْبَةُ بْنُ خَالِدٍ، حَدَّثَنَا سُهَيْلُ بْنُ أَبِي حَزْمٍ، عَنْ ثَابِتٍ، عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ ـ صلى الله عليه وسلم ـ قَالَ فِي هَذِهِ الآيَةِ ‏{هُوَ أَهْلُ التَّقْوَى وَأَهْلُ الْمَغْفِرَةِ }‏ قَالَ رَسُولُ اللَّهِ ـ صلى الله عليه وسلم ـ ‏\"‏ قَالَ رَبُّكُمْ أَنَا أَهْلٌ أَنْ أُتَّقَى فَلاَ يُشْرَكَ بِي غَيْرِي وَأَنَا أَهْلٌ لِمَنِ اتَّقَى أَنْ يُشْرِكَ بِي أَنْ أَغْفِرَ لَهُ ‏\"‏ ‏.‏","v":[]}]};